TypeScript (AsyncIterator + callback shim):

// usage: for await (const e of client.stream(request)) { if (e.event === 'token') console.log(e.payload.token); }

interface StreamEvent<T = any> {
  event: string;
  seq: number;
  payload: T;
  schema?: string | null;
}

// simplified shim: exposes both iterator and onEvent(fn)
class StreamHandle<T> implements AsyncIterable<StreamEvent<T>> {
  private reader: ReadableStreamDefaultReader<string>;
  private callbacks: Array<(e: StreamEvent<T>) => void> = [];

  constructor(reader: ReadableStreamDefaultReader<string>) { this.reader = reader; }

  async *[Symbol.asyncIterator]() {
    for (;;) {
      const { value, done } = await this.reader.read();
      if (done) return;
      const event = JSON.parse(value) as StreamEvent<T>;
      this.callbacks.forEach(cb => cb(event));
      yield event;
    }
  }

  onEvent(cb: (e: StreamEvent<T>) => void) { this.callbacks.push(cb); }
}

// Example: tool invocation flow in app code
(async () => {
  const stream = await client.startStream({ prompt: 'call calculator' });
  for await (const e of stream) {
    if (e.event === 'tool_request') {
      const { request_id, tool, args } = e.payload;
      const result = await localTools[tool](args);
      await client.sendToolResponse({ request_id, result });
    }
    if (e.event === 'structured_chunk') {
      // reassemble structured output client-side or use schema to validate
    }
  }
})();

Python (async generator + callback shim):

# usage: async for e in client.stream(req): ...

from typing import TypedDict, Optional
from dataclasses import dataclass
import json

@dataclass
class StreamEvent:
    event: str
    seq: int
    payload: dict
    schema: Optional[str] = None

class StreamHandle:
    def __init__(self, aio_reader):
        self._reader = aio_reader
        self._callbacks = []

    def on_event(self, cb):
        self._callbacks.append(cb)

    async def __aiter__(self):
        while True:
            line = await self._reader.readline()
            if not line:
                return
            e = StreamEvent(**json.loads(line))
            for cb in self._callbacks:
                cb(e)
            yield e

