Go (channel-based iterator + subscriber):

// usage: for e := range stream.Chan() { switch e.Event { case "token": ... } }

package sdk

import "encoding/json"

type StreamEvent struct {
  Event   string          `json:"event"`
  Seq     int             `json:"seq"`
  Payload json.RawMessage `json:"payload"`
  Schema  string          `json:"schema,omitempty"`
}

type StreamHandle struct {
  ch chan StreamEvent
}

func (s *StreamHandle) Chan() <-chan StreamEvent { return s.ch }

// Example reconstruction of structured chunks
for e := range handle.Chan() {
  switch e.Event {
  case "tool_request":
    var p ToolRequest
    json.Unmarshal(e.Payload, &p)
    res := callLocalTool(p.Tool, p.Args)
    client.SendToolResponse(p.RequestID, res)
  case "structured_chunk":
    // accumulate by schema/request id until structured_done
  }
}
